// An expression tree in object style: one struct per operator, each with an `eval` method that
// evaluates its children through method calls, and a `show` method that renders it.
struct Num {
    v: i64,
}

impl Num {
    fn eval(self) -> i64 {
        return self.v;
    }
    fn show(self) -> str {
        return str(self.v);
    }
}

struct Add {
    l: Num,
    r: Num,
}

impl Add {
    fn eval(self) -> i64 {
        let a = self.l.eval();
        let b = self.r.eval();
        return a + b;
    }
    fn show(self) -> str {
        return "add(" + self.l.show() + ", " + self.r.show() + ")";
    }
}

struct Sub {
    l: Num,
    r: Num,
}

impl Sub {
    fn eval(self) -> i64 {
        let a = self.l.eval();
        let b = self.r.eval();
        return a - b;
    }
    fn show(self) -> str {
        return "sub(" + self.l.show() + ", " + self.r.show() + ")";
    }
}

